// ─── File: ConsistencySagaDemo.java ───
// Runnable demo: orchestrated Saga + transactional outbox + idempotent consumer.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ConsistencySagaDemo {

    private static final Logger log = Logger.getLogger("consistency");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountService accounts = new AccountService();
        FraudService fraud = new FraudService(new BigDecimal("500000"));
        OutboxTable outbox = new OutboxTable();
        NotificationConsumer notifier = new NotificationConsumer();
        OutboxRelay relay = new OutboxRelay(outbox, notifier);
        TransferOrchestrator orchestrator = new TransferOrchestrator(accounts, fraud, outbox);

        log.info("=== SUCCESS Saga: Rs.50,000 (below fraud threshold) ===");
        orchestrator.execute("SAV2001", "CUR3001", new BigDecimal("50000"));
        relay.drain();          // publish outbox events reliably
        relay.drain();          // re-drain simulates duplicate delivery → consumer idempotent

        log.info("=== FAILURE Saga: Rs.800,000 (fraud rejects → compensate) ===");
        orchestrator.execute("SAV2001", "CUR3001", new BigDecimal("800000"));
        relay.drain();
    }
}

// ─── model/Account.java ───
class Account {
    final String id; BigDecimal balance;
    Account(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
}

// ─── model/TransferEvent.java ───
class TransferEvent {
    final String eventId; final String type; final String payload;
    TransferEvent(String eventId, String type, String payload) {
        this.eventId = eventId; this.type = type; this.payload = payload;
    }
}

// ─── service/AccountService.java — local ACID txn + outbox write together ───
class AccountService {
    private static final Logger log = Logger.getLogger("consistency");
    private final Map<String, Account> db = new HashMap<>();
    AccountService() { db.put("SAV2001", new Account("SAV2001", new BigDecimal("1000000")));
                       db.put("CUR3001", new Account("CUR3001", new BigDecimal("250000"))); }

    // Local transaction: debit + credit + outbox row, atomically.
    void debitAndCredit(String from, String to, BigDecimal amt, OutboxTable outbox, String eventId) {
        Account f = db.get(from), t = db.get(to);
        if (f.balance.compareTo(amt) < 0) throw new IllegalStateException("insufficient funds");
        f.balance = f.balance.subtract(amt);
        t.balance = t.balance.add(amt);
        // SAME local transaction: insert outbox event so it can never be lost (no dual-write)
        outbox.insert(new TransferEvent(eventId, "TransferDebited",
                from + "->" + to + ":" + amt));
        log.info(() -> "[ACCOUNT] debit " + from + " credit " + to + " Rs." + amt + " + outbox row (1 txn)");
    }

    // Compensating transaction: undo the debit/credit.
    void compensate(String from, String to, BigDecimal amt) {
        db.get(from).balance = db.get(from).balance.add(amt);
        db.get(to).balance = db.get(to).balance.subtract(amt);
        log.warning(() -> "[ACCOUNT] COMPENSATE: returned Rs." + amt + " to " + from);
    }
    BigDecimal balanceOf(String id) { return db.get(id).balance; }
}

// ─── service/FraudService.java ───
class FraudService {
    private final BigDecimal rejectAbove;
    FraudService(BigDecimal rejectAbove) { this.rejectAbove = rejectAbove; }
    boolean isApproved(BigDecimal amt) { return amt.compareTo(rejectAbove) <= 0; }
}

// ─── outbox/OutboxTable.java ───
class OutboxTable {
    final List<TransferEvent> rows = new ArrayList<>();
    final Set<String> publishedIds = new HashSet<>();
    void insert(TransferEvent e) { rows.add(e); }
}

// ─── outbox/OutboxRelay.java — drains outbox, publishes at-least-once ───
class OutboxRelay {
    private static final Logger log = Logger.getLogger("consistency");
    private final OutboxTable outbox; private final NotificationConsumer consumer;
    OutboxRelay(OutboxTable outbox, NotificationConsumer consumer) { this.outbox = outbox; this.consumer = consumer; }
    void drain() {
        for (TransferEvent e : outbox.rows) {
            // at-least-once: we may re-deliver; consumer must be idempotent
            log.fine(() -> "[RELAY] publishing " + e.eventId);
            consumer.onEvent(e);
            outbox.publishedIds.add(e.eventId);
        }
    }
}

// ─── consumer/NotificationConsumer.java — idempotent ───
class NotificationConsumer {
    private static final Logger log = Logger.getLogger("consistency");
    private final Set<String> processed = new HashSet<>();
    void onEvent(TransferEvent e) {
        if (!processed.add(e.eventId)) {   // add() returns false if already present
            log.fine(() -> "[NOTIFY] duplicate " + e.eventId + " ignored (idempotent)");
            return;
        }
        log.info(() -> "[NOTIFY] SMS sent for " + e.type + " " + e.payload);
    }
}

// ─── orchestrator/TransferOrchestrator.java — orchestrated Saga ───
class TransferOrchestrator {
    private static final Logger log = Logger.getLogger("consistency");
    private final AccountService accounts; private final FraudService fraud; private final OutboxTable outbox;
    TransferOrchestrator(AccountService a, FraudService f, OutboxTable o) { accounts = a; fraud = f; outbox = o; }

    void execute(String from, String to, BigDecimal amt) {
        String eventId = "EVT-" + UUID.randomUUID().toString().substring(0, 8);
        // Step 1: local txn debit/credit + outbox (strong consistency within account service)
        accounts.debitAndCredit(from, to, amt, outbox, eventId);
        // Step 2: fraud check
        if (!fraud.isApproved(amt)) {
            log.severe(() -> "[FRAUD] rejected Rs." + amt + " — running compensation");
            accounts.compensate(from, to, amt);   // Saga compensation
            return;
        }
        log.info(() -> "[SAGA] completed; " + from + " balance now Rs." + accounts.balanceOf(from));
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
